description:
Exploration question: Trace what happens, in order, when a client sends `POST /orders`, from the route to the database write.

Files read (every line is numbered as `line | code`; this is everything that has been read):

`src/routes/orders.ts`
```
1 | import { Router } from "../http/router";
2 | import { createOrder } from "../services/orders";
3 | import { requireAuth } from "../http/auth";
4 | 
5 | export const orders = Router();
6 | 
7 | orders.post("/orders", requireAuth, async (req, res) => {
8 |   const order = await createOrder(req.user.id, req.body.items);
9 |   res.status(201).json(order);
10 | });
```

`src/http/auth.ts`
```
1 | export function requireAuth(req: Req, res: Res, next: Next) {
2 |   const token = req.headers.authorization;
3 |   if (!token) return res.status(401).end();
4 |   req.user = verifyToken(token);
5 |   next();
6 | }
```

`src/services/orders.ts`
```
1 | import { insertOrder } from "../repo/orders";
2 | import { priceItems } from "./pricing";
3 | 
4 | export async function createOrder(userId: string, items: Item[]) {
5 |   const priced = priceItems(items);
6 |   if (priced.total <= 0) throw new Error("empty order");
7 |   return insertOrder({ userId, ...priced });
8 | }
```

`src/services/pricing.ts`
```
1 | export function priceItems(items: Item[]) {
2 |   const total = items.reduce((sum, i) => sum + i.unitCents * i.qty, 0);
3 |   return { items, total };
4 | }
```

`src/repo/orders.ts`
```
1 | import { db } from "../db";
2 | 
3 | export async function insertOrder(row: NewOrder) {
4 |   const result = await db.execute(
5 |     "INSERT INTO orders (user_id, total) VALUES (?, ?)",
6 |     [row.userId, row.total],
7 |   );
8 |   return { id: result.insertId, ...row };
9 | }
```

